// 전: 시간·네트워크가 안에 박혀 있어 테스트 불가
async function expire(order) {
  if (Date.now() - order.createdAt > 3600_000) await fetch('/api/expire', …);
}

// 후: 이음매 두 개(now, api)
async function expire(order, { now = () => Date.now(), api = realApi } = {}) {
  if (now() - order.createdAt > 3600_000) await api.expire(order.id);
}
